<?php
namespace App\Livewire\Admin\WhatsApp;use App\Jobs\SendWhatsAppMessageJob;use App\Models\WhatsAppConversation;use App\Models\WhatsAppMessage;use App\Services\WhatsAppChatFolderService;use App\Services\WhatsAppLeadService;use Illuminate\Support\Str;use Livewire\Component;
class Show extends Component{public WhatsAppConversation $conversation;public string $reply='';public ?int $folder_id=null;public function mount():void{$this->authorizeChat();$this->conversation->markAsRead();$this->refreshChat();$this->folder_id=$this->conversation->folder_id;}private function authorizeChat():void{$u=auth()->user();abort_unless($u&&(($u->isAdmin()&&$this->conversation->isAssigned())||($u->isSales()&&$this->conversation->isAssignedTo($u))),403);}private function refreshChat():void{$this->conversation->load(['contact','lead','folder','messages.sentByUser']);}public function send():void{$this->authorizeChat();$this->validate(['reply'=>['required','string','max:4096']]);$message=WhatsAppMessage::create(['whatsapp_conversation_id'=>$this->conversation->id,'wamid'=>'local-'.Str::uuid(),'direction'=>'outbound','type'=>'text','body'=>trim($this->reply),'status'=>'pending','sent_by_user_id'=>auth()->id(),'sent_at'=>now()]);SendWhatsAppMessageJob::dispatch($message->id);$this->conversation->update(['last_message_at'=>$message->sent_at,'last_message_preview'=>Str::limit($message->body,120)]);$this->reply='';$this->refreshChat();}public function convert(WhatsAppLeadService $service){$this->authorizeChat();abort_if($this->conversation->lead_id,422);$lead=$service->createFromConversation($this->conversation);session()->flash('success','Lead created from WhatsApp.');return $this->redirectRoute('admin.leads.show',$lead,navigate:true);}public function move(WhatsAppChatFolderService $service):void{$this->authorizeChat();$folder=$this->folder_id?auth()->user()->whatsappChatFolders()->findOrFail($this->folder_id):null;$service->moveConversation($this->conversation,auth()->user(),$folder);$this->refreshChat();}public function render(){return view('livewire.admin.whatsapp.show',['folders'=>auth()->user()->whatsappChatFolders()->orderBy('position')->get()])->layout('components.layouts.admin',['title'=>$this->conversation->contact?->displayName()??'WhatsApp chat']);}}
